//! 🧪️ Source-bound property definition SETs keep exact references, cardinality, uniqueness and paid page controls.
use super::*;
fn contract()->serde_json::Value{serde_json::from_str(include_str!("🧪️tests/type-set-select-input.json")).unwrap()}
fn value(row:&serde_json::Value)->IfcValue{match row["kind"].as_str().unwrap(){"unset"=>IfcValue::Unset,"string"=>IfcValue::String(row["value"].as_str().unwrap().into()),"reference"=>IfcValue::Reference(row["value"].as_str().unwrap().parse().unwrap()),"real"=>IfcValue::Real(f64::from_bits(row["value"]["bits"].as_str().unwrap().parse().unwrap())),"aggregate"=>IfcValue::Aggregate(row["value"].as_array().unwrap().iter().map(value).collect()),"typedValue"=>IfcValue::TypedValue(IfcTypedValue{name:row["value"]["name"].as_str().unwrap().into(),items:row["value"]["items"].as_array().unwrap().iter().map(value).collect()}),_=>panic!("closed source fixture")}}
fn source(law:&serde_json::Value)->Arc<IfcSnapshot>{Arc::new(IfcSnapshot{entities:law["source"]["entities"].as_array().unwrap().iter().map(|row|IfcEntity{id:row["id"].as_str().unwrap().parse().unwrap(),name:row["name"].as_str().unwrap().into(),args:row["args"].as_array().unwrap().iter().map(value).collect(),complex:row["complex"].as_array().unwrap().iter().map(|part|IfcComplexType{name:part["name"].as_str().unwrap().into(),args:part["args"].as_array().unwrap().iter().map(value).collect()}).collect()}).collect(),..Default::default()})}
fn event(law:&serde_json::Value,row:&serde_json::Value)->editing::SnapshotEditEvent{editing::SnapshotEditEvent::SetValue{path:"/entities/0".into(),value:super::type_input_tests::raw(&serde_json::json!({"$ifcType":law["entity"],"$ifcInputs":if row["input"].is_null(){serde_json::json!([])}else{serde_json::json!([{"index":law["index"],"value":row["input"]}])}}))}}
#[test]
fn original_set_select_kind_requires_the_complete_reference_and_released_set_domain(){
 if DetailsTestProfile::catalog().schema!="IFC4X3_ADD2"{return;}
 let attribute=DetailsTestProfile::normalization_attribute("IFCRELDEFINESBYPROPERTIES",1,true).unwrap().unwrap();let mut cursor=super::super::super::type_input_kind::Cursor::default();let mut complete=None;for turn in 0..1024{let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance::<DetailsTestProfile>(attribute.type_expr));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));if let Some(kind)=answer.unwrap(){complete=Some(kind);assert!(turn>=2);break;}}assert_eq!(complete,Some(super::super::super::type_input_kind::Kind::Select));assert_eq!(cursor.reference_member(),Some(0));let expression=DetailsTestProfile::defined_type_expression("IFCPROPERTYSETDEFINITIONSET").unwrap();let mut member=super::super::super::type_input_kind::Cursor::default();let mut complete=None;for _ in 0..1024{if let Some(kind)=member.advance_selected::<DetailsTestProfile>(expression).unwrap(){complete=Some(kind);break;}}assert_eq!(complete,Some(super::super::super::type_input_kind::Kind::Set));
}
#[test]
fn original_set_selects_use_central_actual_carriers_and_exact_inverse_without_sorting_or_deduplication(){
 if DetailsTestProfile::catalog().schema!="IFC4X3_ADD2"{return;}
 let law=contract();for row in law["cases"].as_array().unwrap(){let snapshot=source(&law);let mut caller=OriginalWorkFixture::new();let mut work=Work::new(editing::SET_SNAPSHOT_VALUE_ACTION_ID);inputs(&snapshot,event(&law,row),&mut caller,&mut work,|input,caller,work|{let mut result=None;for turn in 0..1000000{match caller.work_turn(grant(),1,|cx|work.step(input,cx)){Ok(ArtifactCommandWorkStep::Complete(emit))=>{result=Some(Ok(emit));break;},Err(error)=>{result=Some(Err(error));break;},_=>{}}assert!(turn<999999);}let result=result.unwrap();assert_eq!(result.is_ok(),row["ready"].as_bool().unwrap(),"{}",row["id"]);if let Ok(emit)=result{assert_eq!(emit.artifact_mutations.len(),1);assert!(matches!(emit.artifact_mutations[0],IfcMutation::SetEntityArg(_)));let mutation=&emit.artifact_mutations[0];let inverse=mutation.inverse(&snapshot).unwrap();let mut next=protocol::apply_diff_cold(mutation.diff(&snapshot).diff(),&snapshot).unwrap();assert!(ifc_arguments_identical(&next.entities[0].args[1..2],&[value(&row["input"])]));assert!(ifc_complex_identical(&next.entities[0].complex,&snapshot.entities[0].complex));for mutation in inverse{next=protocol::apply_diff_cold(mutation.diff(&next).diff(),&next).unwrap();}assert!(ifc_arguments_identical(&next.entities[0].args,&snapshot.entities[0].args));assert!(ifc_complex_identical(&next.entities[0].complex,&snapshot.entities[0].complex));}super::constituent_optional_shape_tests::close_with_denials(caller,work);assert!(work.terminal_is_empty());});caller.finish();}
}
#[test]
fn original_donated_set_controls_preserve_every_page_and_fixed_array_operation_under_denied_axes(){
 use semio_framework_plugin::{action_staging::*,app::staged_form::*};
 type Guidance=super::super::super::type_guidance::IfcTypeInputSourceWork<DetailsTestProfile>;
 if DetailsTestProfile::catalog().schema!="IFC4X3_ADD2"{return;}
 let law=contract();for row in law["cases"].as_array().unwrap(){let pages=if row["id"]=="set-eighteen"{3}else{1};for page in 0..pages{let snapshot=source(&law);let editing::SnapshotEditEvent::SetValue{path,value}=event(&law,row)else{unreachable!()};let mut donor=Some(StagedFormRequest{token:StagedFormToken{action:editing::SET_SNAPSHOT_VALUE_ACTION_ID.into(),window:"original-set-select".into(),generation:"1".into(),revision:"0".repeat(64)},locale:semio_framework_ui_locale::Locale::De,args:DslValue::Object(vec![("path".into(),DslValue::String(path)),("value".into(),value)]),page:if page==0{None}else{Some(StagedFormPage{field_offset:"0".into(),diagnostic_offset:"0".into(),choice:Some(StagedFormChoicePage{path:vec!["entities".into(),"0".into(),"args".into(),"1".into()],offset:law["pages"][page]["offset"].as_str().unwrap().into()})})}});let mut caller=OriginalWorkFixture::new();let mut guide=Some(Guidance::default());let mut output=None;assert!(caller.work_turn(grant(),1,|cx|guide.as_mut().unwrap().receive(&mut donor,&snapshot,[0;32],cx)).unwrap());for turn in 0..1000000{let demand=guide.as_ref().unwrap().demands().unwrap();let(repeated,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||guide.as_ref().unwrap().demands());assert_eq!(repeated.unwrap(),demand);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));for axis in 0..6{let mut denied=grant();let mut fuel=1;match axis{0=>denied.maximum_items=0,1 if demand.copy_bytes>0=>denied.maximum_copy_bytes=demand.copy_bytes-1,2 if demand.capacity_bytes>0=>denied.maximum_capacity_bytes=demand.capacity_bytes-1,3 if demand.release_bytes>0=>denied.maximum_release_bytes=demand.release_bytes-1,4 if demand.depth>0=>denied.maximum_depth=demand.depth-1,5=>fuel=0,_=>continue};let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(denied,fuel,|cx|{let before=cx.retained_progress();let answer=guide.as_mut().unwrap().advance(&snapshot,[0;32],cx);assert_eq!(before,cx.retained_progress());answer}));assert!(!answer.unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}if caller.work_turn(grant(),1,|cx|guide.as_mut().unwrap().advance(&snapshot,[0;32],cx)).unwrap(){break;}assert!(turn<999999);}assert!(caller.work_turn(grant(),1,|cx|guide.as_mut().unwrap().take(&mut output,cx)).unwrap());let prepared=output.as_ref().unwrap();assert_eq!(prepared.status().ready,row["ready"].as_bool().unwrap());assert!(prepared.controls()<=STAGED_FORM_BODY_LIMITS.controls);let control=prepared.control(0).unwrap();let StagedScalarKind::Choice{choices,..}=control.scalar.kind else{panic!("complete actual SET SELECT choices")};assert_eq!(choices.iter().map(|choice|choice.key).collect::<Vec<_>>(),["IFCPROPERTYSETDEFINITION","IFCPROPERTYSETDEFINITIONSET"]);if row["input"]["kind"]=="typedValue"{let StagedBodyBinding::Action(binding)=control.binding.unwrap()else{panic!("source SET discriminator binding")};let selected=DslValue::String("IFCPROPERTYSETDEFINITIONSET".into());let StagedFormBorrowedEdit::Set{value,..}=binding.plan(prepared.status(),Some(&selected)).unwrap().last().unwrap()else{panic!("actual complete typed SET option")};assert_eq!(value,&super::type_input_tests::raw(&row["input"]));let control=prepared.control(1).unwrap();assert!(matches!(control.scalar.kind,StagedScalarKind::Button{page:false}));let StagedBodyBinding::Action(binding)=control.binding.unwrap()else{panic!("original array operation")};let edit=binding.plan(prepared.status(),None).unwrap().last().unwrap();let StagedFormBorrowedEdit::Append{value,..}=edit else{panic!("fixed original SET Append")};if row["input"]["value"]["items"].as_array().unwrap().is_empty(){assert_eq!(value.get("kind").and_then(DslValue::as_str),Some("aggregate"));assert!(matches!(value.get("value"),Some(DslValue::Array(values))if values.is_empty()));}else{assert_eq!(value.get("kind").and_then(DslValue::as_str),Some("reference"));assert_eq!(value.get("value").and_then(DslValue::as_str),Some(""));}if row["id"]=="set-eighteen"{for (local,id)in law["pages"][page]["members"].as_array().unwrap().iter().enumerate(){let control=prepared.control(2+2*local).unwrap();let StagedScalarKind::Text{value}=control.scalar.kind else{panic!("actual original member input")};assert_eq!(value,id.as_str().unwrap());let remove=prepared.control(3+2*local).unwrap();assert!(matches!(remove.scalar.kind,StagedScalarKind::Button{page:false}));let StagedBodyBinding::Action(binding)=remove.binding.unwrap()else{panic!("original indexed remove")};assert!(matches!(binding.plan(prepared.status(),None).unwrap().last(),Some(StagedFormBorrowedEdit::Remove{..})));}}}caller.cancel().cancel_now();super::type_guidance_request_tests::retire_owner(&mut caller,&mut output);super::type_guidance_request_tests::retire_owner(&mut caller,&mut guide);assert_eq!(Arc::strong_count(&snapshot),1);caller.finish();}}
}
